def now() -> datetime:
    return datetime.now()


def iso(dt: Optional[datetime]) -> Optional[str]:
    return dt.isoformat() if dt else None


def parse_dt(value: Any) -> Optional[datetime]:
    if not value:
        return None
    try:
        return datetime.fromisoformat(str(value))
    except (TypeError, ValueError):
        return None


def load_json(path: Path, default: Any) -> Any:
    try:
        if not path.exists():
            return default
        with path.open("r", encoding="utf-8") as f:
            data = json.load(f)
        return data
    except (OSError, json.JSONDecodeError) as exc:
        logger.error("Не удалось загрузить %s: %s", path, exc)
        return default


def save_json(path: Path, data: Any) -> bool:
    """Атомарное сохранение, чтобы падение процесса не уничтожило JSON."""
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp_name = tempfile.mkstemp(
            prefix=f".{path.name}.",
            suffix=".tmp",
            dir=str(path.parent),
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp_name, path)
        finally:
            if os.path.exists(tmp_name):
                os.unlink(tmp_name)
        return True
    except OSError as exc:
        logger.error("Не удалось сохранить %s: %s", path, exc)
        return False


def esc(value: Any) -> str:
    return html.escape(str(value if value is not None else ""))


def tg_username(user) -> str:
    return f"@{user.username}" if user and user.username else "без username"


def copyable(value: Any) -> str:
    return f"<code>{esc(value)}</code>"


def club_label(club: Optional[str]) -> str:
    if not club:
        return "Свободный агент"
    return f"{CLUB_FLAGS.get(club, '🏟️')} {club}"


def find_club(value: str) -> Optional[str]:
    value = re.sub(r"\s+", " ", value.strip())
    if not value or len(value) > 80:
        return None
    aliases = {
        "реал": "Реал Мадрид", "реал мадрид": "Реал Мадрид", "псж": "ПСЖ",
        "psg": "ПСЖ", "боруссия дортмунд": "Боруссия", "дортмунд": "Боруссия",
        "тоттенхэм": "Тоттенхем", "буэнос-айрес": "Буэнос Айрес",
        "буэнос айрес": "Буэнос Айрес",
    }
    key = value.casefold()
    if key in aliases:
        return aliases[key]
    for name in CLUB_NAMES:
        if name.casefold() == key:
            return name
    return value


def find_nation(value: str) -> Optional[str]:
    value = re.sub(r"\s+", " ", value.strip())
    if not value or len(value) > 80:
        return None
    aliases = {"сша": "США", "usa": "США", "южная корея": "Корея", "корея": "Корея"}
    key = value.casefold()
    if key in aliases:
        return aliases[key]
    for name in NATIONAL_NAMES:
        if name.casefold() == key:
            return name
    return value


