class RSSBot:
    def __init__(self):
        self.users = load_json(FILES["users"], {})
        self.transfers = load_json(FILES["transfers"], {})
        self.search_club_requests = load_json(FILES["search_club_requests"], {})
        self.search_nation_requests = load_json(FILES["search_nation_requests"], {})
        self.ads = load_json(FILES["ads"], {})
        self.admins = load_json(FILES["admins"], {"admins": []})
        self.support = load_json(FILES["support"], {})
        self.bans = load_json(FILES["bans"], {"banned": [], "ban_info": {}})
        self.history = load_json(
            FILES["history"],
            {"transfers": [], "career_changes": [], "club_events": []},
        )
        self.nick_requests = load_json(FILES["nick_requests"], {})
        self.roblox_requests = load_json(FILES["roblox_requests"], {})
        self.transfer_requests = load_json(FILES["transfer_requests"], {})
        self.career_requests = load_json(FILES["career_requests"], {})
        self.payments = load_json(FILES["payments"], {})
        self.frozen_clubs = load_json(FILES["frozen_clubs"], {})
        self.custom_clubs = load_json(FILES["custom_clubs"], {})
        self.custom_nations = load_json(FILES["custom_nations"], {})
        if not isinstance(self.frozen_clubs, dict): self.frozen_clubs = {}
        if not isinstance(self.custom_clubs, dict): self.custom_clubs = {}
        if not isinstance(self.custom_nations, dict): self.custom_nations = {}

        self._normalize_data()
        self.save_users()

    def _normalize_data(self):
        if not isinstance(self.users, dict):
            self.users = {}
        if not isinstance(self.transfers, dict):
            self.transfers = {}
        if not isinstance(self.search_club_requests, dict):
            self.search_club_requests = {}
        if not isinstance(self.search_nation_requests, dict):
            self.search_nation_requests = {}
        if not isinstance(self.ads, dict):
            self.ads = {}
        if not isinstance(self.admins, dict):
            self.admins = {"admins": [], "testers": []}
        if not isinstance(self.support, dict):
            self.support = {}
        if not isinstance(self.bans, dict):
            self.bans = {"banned": [], "ban_info": {}}
        if not isinstance(self.history, dict):
            self.history = {}
        if not isinstance(self.nick_requests, dict):
            self.nick_requests = {}
        if not isinstance(self.roblox_requests, dict):
            self.roblox_requests = {}
        if not isinstance(self.transfer_requests, dict):
            self.transfer_requests = {}
        if not isinstance(self.career_requests, dict):
            self.career_requests = {}
        if not isinstance(self.payments, dict):
            self.payments = {}

        for _u in self.users.values():
            _u.setdefault("last_club_transfer_date", _u.get("last_transfer_date"))
            _u.setdefault("last_nation_transfer_date", _u.get("last_transfer_date"))
            _u.setdefault("last_club_search_date", _u.get("last_search_date"))
            _u.setdefault("last_nation_search_date", _u.get("last_search_date"))
            _u.setdefault("username", None)
            # Старые профили с уже выбранной позицией считаем подтверждёнными.
            if "position_confirmed" not in _u:
                _u["position_confirmed"] = bool(_u.get("position") not in (None, "", "Не выбрана"))

        self.bans.setdefault("banned", [])
        self.bans.setdefault("ban_info", {})
        self.history.setdefault("transfers", [])
        self.history.setdefault("career_changes", [])
        self.history.setdefault("club_events", [])
        self.admins.setdefault("admins", [])
        self.admins.setdefault("testers", [])

        # Миграция старых пользователей.
        for uid, user in self.users.items():
            if not isinstance(user, dict):
                self.users[uid] = new_user(type("U", (), {"id": uid, "username": None, "first_name": None})())
                continue
            defaults = new_user(
                type(
                    "U",
                    (),
                    {
                        "id": uid,
                        "username": user.get("username"),
                        "first_name": user.get("first_name"),
                    },
                )()
            )
            for key, value in defaults.items():
                user.setdefault(key, value)

    def save_users(self):
        save_json(FILES["users"], self.users)

    def is_admin(self, user_id: int) -> bool:
        return user_id == CREATOR_ID or user_id in self.admins.get("admins", [])

    def is_tester(self, user_id: int) -> bool:
        return user_id in self.admins.get("testers", [])

    def is_staff(self, user_id: int) -> bool:
        return self.is_admin(user_id) or self.is_tester(user_id)

    def is_banned(self, user_id: int) -> bool:
        self._cleanup_expired_bans_local()
        return any(str(x).isdigit() and int(x) == user_id for x in self.bans.get("banned", []))

    def _cleanup_expired_bans_local(self):
        changed = False
        banned = self.bans.setdefault("banned", [])
        info = self.bans.setdefault("ban_info", {})
        active = []
        for uid in banned:
            item = info.get(str(uid), {})
            if item.get("permanent"):
                active.append(uid)
                continue
            end = parse_dt(item.get("end_date"))
            if end and now() < end:
                active.append(uid)
            else:
                changed = True
                info.pop(str(uid), None)
        if changed:
            self.bans["banned"] = active
            save_json(FILES["bans"], self.bans)

    def user(self, user_id: str) -> dict:
        if user_id not in self.users:
            # Вызывается только после start/ensure_user.
            return {}
        return self.users[user_id]

    def ensure_user(self, tg_user) -> dict:
        uid = str(tg_user.id)
        if uid not in self.users:
            self.users[uid] = new_user(tg_user)
        else:
            user = self.users[uid]
            user["username"] = tg_user.username
            user["first_name"] = tg_user.first_name
        self.save_users()
        return self.users[uid]

    def club_is_frozen(self, club: str) -> bool:
        item = self.frozen_clubs.get(club)
        if not item: return False
        end = parse_dt(item.get("until"))
        if end and now() < end: return True
        self.frozen_clubs.pop(club, None); save_json(FILES["frozen_clubs"], self.frozen_clubs); return False

    def club_count(self, club: str) -> int:
        return sum(
            1
            for user in self.users.values()
            if user.get("club") == club and user.get("career_active", True)
        )





    def can_change_nick(self, user_id: str) -> tuple[bool, str]:
        last = parse_dt(self.users.get(user_id, {}).get("last_nick_change"))
        if not last:
            return True, ""
        left = NICK_COOLDOWN - (now() - last)
        if left <= timedelta(0):
            return True, ""
        return False, self.format_duration(left)

    def is_premium(self, user_id: str) -> bool:
        until = parse_dt(self.users.get(user_id, {}).get("premium_until"))
        return bool(until and until > now())

    def has_confirmed_position(self, user_id: str) -> bool:
        user = self.users.get(str(user_id), {})
        position = user.get("position")
        return bool(user.get("position_confirmed") and position not in (None, "", "Не выбрана"))

    def can_search(self, user_id: str, search_type: str = "club") -> tuple[bool, str]:
        if self.is_premium(user_id):
            return True, ""
        key = "last_nation_search_date" if search_type == "nation" else "last_club_search_date"
        last = parse_dt(self.users.get(user_id, {}).get(key))
        if not last:
            return True, ""
        left = SEARCH_COOLDOWN - (now() - last)
        if left <= timedelta(0):
            return True, ""
        return False, self.format_duration(left)

    def resolve_club(self, value: str) -> Optional[str]:
        """Ищет стандартный или кастомный клуб по названию."""
        raw = re.sub(r"\s+", " ", str(value or "").strip())
        if not raw:
            return None
        standard = find_club(raw)
        if standard:
            return standard
        low = raw.casefold()
        for name, data in self.custom_clubs.items():
            candidate = data.get("name", name) if isinstance(data, dict) else str(name)
            if str(candidate).strip().casefold() == low:
                return str(candidate).strip()
        return raw if len(raw) <= 80 else None

    def resolve_nation(self, value: str) -> Optional[str]:
        """Ищет стандартную или кастомную сборную по названию."""
        raw = re.sub(r"\s+", " ", str(value or "").strip())
        if not raw:
            return None
        standard = find_nation(raw)
        if standard:
            return standard
        low = raw.casefold()
        for name, data in self.custom_nations.items():
            candidate = data.get("name", name) if isinstance(data, dict) else str(name)
            if str(candidate).strip().casefold() == low:
                return str(candidate).strip()
        return raw if len(raw) <= 80 else None

    def can_transfer(self, user_id: str, transfer_type: str = "club") -> tuple[bool, str]:
        key = "last_nation_transfer_date" if transfer_type == "nation" else "last_club_transfer_date"
        last = parse_dt(self.users.get(user_id, {}).get(key))
        if not last:
            return True, ""
        cooldown = NATION_TRANSFER_COOLDOWN if transfer_type == "nation" else CLUB_TRANSFER_COOLDOWN
        left = cooldown - (now() - last)
        if left <= timedelta(0):
            return True, ""
        return False, self.format_duration(left)

    @staticmethod
    def format_duration(delta: timedelta) -> str:
        seconds = max(0, int(delta.total_seconds()))
        days, seconds = divmod(seconds, 86400)
        hours, seconds = divmod(seconds, 3600)
        minutes = seconds // 60
        parts = []
        if days:
            parts.append(f"{days} д.")
        if hours:
            parts.append(f"{hours} ч.")
        if minutes and len(parts) < 2:
            parts.append(f"{minutes} мин.")
        return " ".join(parts) or "меньше минуты"

    def make_id(self, store: dict) -> str:
        if not store:
            return "1"
        numeric = []
        for key in store:
            try:
                numeric.append(int(key))
            except (ValueError, TypeError):
                pass
        return str(max(numeric, default=0) + 1)

    @staticmethod
    def two_column_rows(buttons: list[InlineKeyboardButton]) -> list[list[InlineKeyboardButton]]:
        rows = []
        for i in range(0, len(buttons), 2):
            rows.append(buttons[i:i + 2])
        return rows

