    async def approve_career(self, query, context, rid):
        item = self.career_requests.get(rid)
        if not item or item.get("status") != "pending":
            await self.safe_edit(query, "❌ Заявка уже обработана.")
            return
        uid = item["user_id"]
        if uid not in self.users:
            await self.safe_edit(query, "❌ Пользователь не найден.")
            return
        end = now() + CAREER_PAUSE
        old_club = self.users[uid].get("club")
        self.users[uid]["career_active"] = False
        self.users[uid]["career_end_date"] = iso(end)
        self.users[uid]["club"] = None
        if old_club:
            self.users[uid]["last_club"] = old_club
        self.save_users()
        item["status"] = "approved"
        item["approved_by"] = str(query.from_user.id)
        item["approved_at"] = iso(now())
        save_json(FILES["career_requests"], self.career_requests)
        await self.safe_send(
            context.bot,
            int(uid),
            f"🥀 Карьера приостановлена на 30 дней.\nВозврат: {end:%d.%m.%Y %H:%M}",
        )
        if CHANNEL_ID:
            await context.bot.send_message(chat_id=CHANNEL_ID, text=(f"🌅 │ <b>Завершение карьеры</b>\n\n● Игрок — {esc(item.get('player_nick'))}\n● Завершил карьеру\n● Комментарий игрока — {esc(item.get('comment'))}"), parse_mode=ParseMode.HTML)
